package com.rahul.resumable;
import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="upload_parts", uniqueConstraints=@UniqueConstraint(name="uk_upload_part",columnNames={"upload_session_id","part_number"})) @Getter @NoArgsConstructor
public class UploadPart { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="upload_session_id",nullable=false) private UUID uploadSessionId; @Column(name="part_number",nullable=false) private int partNumber; @Column(name="object_key",nullable=false,length=1024) private String objectKey; @Column(name="size_bytes",nullable=false) private long sizeBytes; @Column(name="checksum_sha256",nullable=false,length=64) private String checksumSha256; @Column(name="created_at",nullable=false) private Instant createdAt; public UploadPart(UUID s,int n,String k,long z,String c){uploadSessionId=s;partNumber=n;objectKey=k;sizeBytes=z;checksumSha256=c;createdAt=Instant.now();}}
